import { useState, useEffect, useCallback } from 'react'
import { DataTable, type DataTableColumn } from '@/components/ui/DataTable.js'
import { CurrencyInput } from '@/components/ui/CurrencyInput.js'
import { Button } from '@/components/ui/button.js'
import { Input } from '@/components/ui/input.js'
import { Label } from '@/components/ui/label.js'
import { Textarea } from '@/components/ui/textarea.js'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from '@/components/ui/dialog.js'
import { formatCentsToEuro } from '@/shared/lib/utils.js'
import { showSuccess, showError } from '@/shared/lib/notifications.js'
import { Wrench } from 'lucide-react'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface LaborServiceCatalogItem extends Record<string, unknown> {
  id: string
  name: string
  defaultRate: number
}

interface LaborServiceDetail extends LaborServiceCatalogItem {
  description?: string
  billingType: 'hourly'
}

interface CreateLaborServiceInput {
  name: string
  description?: string
  billingType: 'hourly'
  defaultRate: number
}

interface UpdateLaborServiceInput {
  name?: string
  description?: string
  billingType?: 'hourly'
  defaultRate?: number
}

// ---------------------------------------------------------------------------
// API helpers
// ---------------------------------------------------------------------------

async function fetchLaborServices(search?: string): Promise<{ laborServices: LaborServiceCatalogItem[]; total: number }> {
  const url = search ? `/api/labor-services?search=${encodeURIComponent(search)}` : '/api/labor-services'
  const res = await fetch(url)
  if (!res.ok) throw new Error('Failed to fetch labor services')
  return res.json()
}

async function createLaborService(input: CreateLaborServiceInput): Promise<LaborServiceDetail> {
  const res = await fetch('/api/labor-services', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })
  if (!res.ok) {
    const err = await res.json().catch(() => ({}))
    throw new Error(err.error ?? 'Failed to create labor service')
  }
  return res.json()
}

async function updateLaborService(id: string, input: UpdateLaborServiceInput): Promise<LaborServiceDetail> {
  const res = await fetch(`/api/labor-services/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })
  if (!res.ok) {
    const err = await res.json().catch(() => ({}))
    throw new Error(err.error ?? 'Failed to update labor service')
  }
  return res.json()
}

async function deactivateLaborService(id: string): Promise<void> {
  const res = await fetch(`/api/labor-services/${id}/deactivate`, { method: 'PATCH' })
  if (!res.ok) {
    const err = await res.json().catch(() => ({}))
    throw new Error(err.error ?? 'Failed to deactivate labor service')
  }
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export function LaborServicesPage() {
  const [laborServices, setLaborServices] = useState<LaborServiceCatalogItem[]>([])
  const [totalItems, setTotalItems] = useState(0)
  const [searchTerm, setSearchTerm] = useState('')
  const [currentPage, setCurrentPage] = useState(1)
  const pageSize = 20

  // Modal state
  const [modalOpen, setModalOpen] = useState(false)
  const [editingService, setEditingService] = useState<LaborServiceDetail | null>(null)
  const [submitting, setSubmitting] = useState(false)
  const [deactivatingId, setDeactivatingId] = useState<string | null>(null)

  // Form state
  const [formName, setFormName] = useState('')
  const [formDescription, setFormDescription] = useState('')
  const [formDefaultRate, setFormDefaultRate] = useState(0)

  // Fetch labor services on search/page change
  useEffect(() => {
    let cancelled = false
    fetchLaborServices(searchTerm || undefined).then(({ laborServices: ls, total }) => {
      if (!cancelled) {
        setLaborServices(ls)
        setTotalItems(total)
      }
    }).catch((err) => showError(err.message))

    return () => { cancelled = true }
  }, [searchTerm, currentPage])

  // Reset page when search changes
  const handleSearchChange = useCallback((term: string) => {
    setSearchTerm(term)
    setCurrentPage(1)
  }, [])

  // Open create modal
  const openCreateModal = () => {
    setEditingService(null)
    resetForm()
    setModalOpen(true)
  }

  // Open edit modal
  const openEditModal = (service: LaborServiceCatalogItem) => {
    fetch(`/api/labor-services/${service.id}`)
      .then(res => res.json())
      .then((detail: LaborServiceDetail) => {
        setEditingService(detail)
        setFormName(detail.name)
        setFormDescription(detail.description ?? '')
        setFormDefaultRate(detail.defaultRate)
        setModalOpen(true)
      })
      .catch((err) => showError(err.message))
  }

  // Close modal and reset form
  const closeModal = () => {
    setModalOpen(false)
    setEditingService(null)
    resetForm()
  }

  const resetForm = () => {
    setFormName('')
    setFormDescription('')
    setFormDefaultRate(0)
  }

  // Submit form (create or update)
  const handleSubmit = async () => {
    if (!formName.trim()) {
      showError('Name is required')
      return
    }
    if (formDefaultRate <= 0) {
      showError('Hourly rate must be greater than 0')
      return
    }

    setSubmitting(true)
    try {
      if (editingService) {
        // Update existing service
        await updateLaborService(editingService.id, {
          name: formName.trim(),
          description: formDescription.trim() || undefined,
          defaultRate: formDefaultRate,
        })
        showSuccess('Labor service updated')
      } else {
        // Create new service (billingType is always 'hourly', hidden from UI)
        await createLaborService({
          name: formName.trim(),
          description: formDescription.trim() || undefined,
          billingType: 'hourly' as const,
          defaultRate: formDefaultRate,
        })
        showSuccess('Labor service created')
      }
      closeModal()
    } catch (err) {
      showError(err instanceof Error ? err.message : 'Failed to save labor service')
    } finally {
      setSubmitting(false)
    }
  }

  // Deactivate service with confirmation
  const handleDeactivate = async (service: LaborServiceCatalogItem) => {
    if (!confirm(`Deactivate "${service.name}"? This cannot be undone.`)) return

    setDeactivatingId(service.id)
    try {
      await deactivateLaborService(service.id)
      showSuccess('Labor service deactivated')
    } catch (err) {
      showError(err instanceof Error ? err.message : 'Failed to deactivate labor service')
    } finally {
      setDeactivatingId(null)
    }
  }

  // Column definitions for the DataTable
  const columns: DataTableColumn<LaborServiceCatalogItem>[] = [
    {
      key: 'name',
      header: 'Name',
      render: (item) => <span className="font-medium">{item.name}</span>,
    },
    {
      key: 'defaultRate',
      header: 'Hourly Rate',
      render: (item) => formatCentsToEuro(item.defaultRate),
    },
    {
      key: 'actions',
      header: '',
      render: (item) => (
        <div className="flex items-center gap-2">
          <Button variant="ghost" size="sm" onClick={() => openEditModal(item)}>Edit</Button>
          <Button
            variant="ghost"
            size="sm"
            className="text-red-500 hover:text-red-600"
            disabled={deactivatingId === item.id}
            onClick={() => handleDeactivate(item)}
          >
            {deactivatingId === item.id ? '...' : 'Deactivate'}
          </Button>
        </div>
      ),
    },
  ]

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold flex items-center gap-2">
          <Wrench size={24} />
          Labor Services
        </h1>
        <Button onClick={openCreateModal}>Add Service</Button>
      </div>

      {/* DataTable */}
      <DataTable<LaborServiceCatalogItem>
        data={laborServices}
        columns={columns}
        searchTerm={searchTerm}
        onSearchChange={handleSearchChange}
        totalItems={totalItems}
        currentPage={currentPage}
        pageSize={pageSize}
        onPageChange={(page) => {
          if (page >= 1 && page <= Math.ceil(totalItems / pageSize)) {
            setCurrentPage(page)
          }
        }}
        emptyMessage={'No labor services found. Click "Add Service" to create one.'}
      />

      {/* Create/Edit Modal */}
      <Dialog open={modalOpen} onOpenChange={(open) => !open && closeModal()}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>{editingService ? 'Edit Labor Service' : 'Add New Labor Service'}</DialogTitle>
            <DialogDescription>
              {editingService
                ? `Editing ${editingService.name}`
                : 'Fill in the details for the new labor service.'}
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-4 py-4">
            {/* Name */}
            <div className="space-y-2">
              <Label htmlFor="name">Name *</Label>
              <Input
                id="name"
                value={formName}
                onChange={(e) => setFormName(e.target.value)}
                placeholder="e.g. Standard Repair"
              />
            </div>

            {/* Description */}
            <div className="space-y-2">
              <Label htmlFor="description">Description</Label>
              <Textarea
                id="description"
                value={formDescription}
                onChange={(e) => setFormDescription(e.target.value)}
                placeholder="Optional description"
                rows={2}
              />
            </div>

            {/* Billing Type — hidden (always hourly), shown for clarity */}
            <div className="space-y-2">
              <Label htmlFor="billingType">Billing Type</Label>
              <Input id="billingType" value="Hourly" disabled className="bg-muted" />
            </div>

            {/* Hourly Rate */}
            <div className="space-y-2">
              <Label htmlFor="defaultRate">Default Rate (€/hr) *</Label>
              <CurrencyInput
                id="defaultRate"
                value={formDefaultRate}
                onChange={setFormDefaultRate}
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={closeModal}>Cancel</Button>
            <Button onClick={handleSubmit} disabled={submitting}>
              {submitting ? 'Saving...' : editingService ? 'Save Changes' : 'Create Service'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

import { Hono } from 'hono'
import { z } from 'zod'
import { zValidator } from '@hono/zod-validator'
import {
  browseParts,
  createPart,
  updatePart,
  deactivatePart,
  getPartById,
  createSpecialProduct,
  reconcileStock
} from '../services/product.service.js'
import { PartNotFoundError } from '../services/product.service.js'

const productsRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /parts — Browse the active parts catalog
// ===========================================================================

/**
 * Query params:
 *   - search (optional) — Filter by name (case-insensitive partial match) or exact barcode
 */
productsRoutes.get('/', async (c) => {
  const search = c.req.query('search')
  const result = await browseParts(search || undefined)
  return c.json(result)
})

// ---------------------------------------------------------------------------
// GET /parts/:id — Get a single part detail
// ===========================================================================

productsRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')
  const part = await getPartById(id)

  if (!part) {
    return c.json({ error: 'Part not found', code: 'NOT_FOUND' }, 404)
  }

  return c.json(part)
})

// ---------------------------------------------------------------------------
// POST /parts — Create a new part
// ===========================================================================

const createSchema = z.object({
  barcode: z.string().min(1, 'Barcode is required').max(50),
  name: z.string().min(1, 'Name is required').max(200),
  description: z.string().max(1000).optional(),
  priceNet: z.number().int().positive('Price must be positive'),
  costPrice: z.number().int().nonnegative('Cost price must be non-negative').optional(),
  quantityOnHand: z.number().int().nonnegative('Quantity on hand must be non-negative'),
})

productsRoutes.post('/', zValidator('json', createSchema), async (c) => {
  const input = c.req.valid('json')
  try {
    const part = await createPart(input)
    return c.json(part, 201)
  } catch (err) {
    console.error('[POST /parts] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// PATCH /parts/:id — Update a part (partial update allowed)
// ===========================================================================

const updateSchema = z.object({
  barcode: z.string().min(1).max(50).optional(),
  name: z.string().min(1).max(200).optional(),
  description: z.string().max(1000).optional(),
  priceNet: z.number().int().positive().optional(),
  costPrice: z.number().int().nonnegative().optional(),
  quantityOnHand: z.number().int().nonnegative().optional(),
}).refine(data => Object.keys(data).length > 0, {
  message: 'At least one field must be provided for update'
})

productsRoutes.patch('/:id', zValidator('json', updateSchema), async (c) => {
  const id = c.req.param('id')

  try {
    const input = c.req.valid('json')
    const part = await updatePart(id, input)
    return c.json(part)
  } catch (err) {
    if (err instanceof PartNotFoundError) {
      return c.json({ error: 'Part not found', code: 'NOT_FOUND' }, 404)
    }

    console.error('[PATCH /parts/:id] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// PATCH /parts/:id/deactivate — Soft-delete a part
// ===========================================================================

productsRoutes.patch('/:id/deactivate', async (c) => {
  const id = c.req.param('id')

  try {
    await deactivatePart(id)
    return c.json({ success: true, message: 'Part deactivated' })
  } catch (err) {
    if (err instanceof PartNotFoundError) {
      return c.json({ error: 'Part not found', code: 'NOT_FOUND' }, 404)
    }

    console.error('[PATCH /parts/:id/deactivate] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// PATCH /parts/:id/reconcile-stock — Recalculate quantityOnHand from movements
// ===========================================================================

productsRoutes.patch('/:id/reconcile-stock', async (c) => {
  const id = c.req.param('id')

  try {
    const part = await reconcileStock(id)
    return c.json(part)
  } catch (err) {
    if (err instanceof PartNotFoundError) {
      return c.json({ error: 'Part not found', code: 'NOT_FOUND' }, 404)
    }

    console.error('[PATCH /parts/:id/reconcile-stock] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// POST /parts/special — Create a special (ad-hoc) product
// ===========================================================================

const createSpecialSchema = z.object({
  name: z.string().min(1, 'Name is required').max(200),
  priceNet: z.number().int().positive('Price must be positive'),
  vatRateBasisPoints: z.number().int().nonnegative().optional()
})

productsRoutes.post('/special', zValidator('json', createSpecialSchema), async (c) => {
  const input = c.req.valid('json')
  try {
    const part = await createSpecialProduct(input)
    return c.json(part, 201)
  } catch (err) {
    console.error('[POST /parts/special] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

export default productsRoutes

import crypto from 'crypto'
import { db } from '@/db/index.js'
import { parts, stockMovements, type Part, type NewPart, type NewStockMovement } from '@/db/schema.js'
import { and, eq, or, asc, count, sql, sum as drizzleSum } from 'drizzle-orm'
import { Product } from '@shared/types/product.js'
import { createPartSchema, updatePartSchema, type CreatePartInput, type UpdatePartInput } from '../validations/parts-validation.js'

// ---------------------------------------------------------------------------
// DTO shapes returned by the API (compact catalog item + full detail)
// These are derived from the shared Product domain type.
// ---------------------------------------------------------------------------

export interface PartCatalogItem {
  id: string
  barcode: string
  name: string
  priceNet: number
  quantityOnHand: number
}

/** Full part detail for create/edit forms (optional fields). */
export interface PartDetail {
  id: string
  barcode: string
  name: string
  description?: string
  priceNet: number
  costPrice?: number
  quantityOnHand: number
}

/** Response envelope for paginated catalog queries. */
export interface PartsCatalogResponse {
  parts: PartCatalogItem[]
  total: number
}

// ---------------------------------------------------------------------------
// Public API — Read operations
// ---------------------------------------------------------------------------

/**
 * Browse the active parts catalog with optional search filtering.
 *
 * Search matches on `name` (case-insensitive partial) or exact `barcode`.
 * Returns only active parts with stock quantities.
 */
export async function browseParts(search?: string): Promise<PartsCatalogResponse> {
  const [results, total] = await Promise.all([
    listParts(search),
    countParts(search)
  ])

  return {
    parts: results.map(toCatalogItem),
    total
  }
}

/**
 * Look up a single part by ID (active only).
 */
export async function getPartById(id: string): Promise<PartDetail | undefined> {
  const result = await findPartById(id)
  return result ? toPartDetail(result) : undefined
}

/**
 * Look up a single part by barcode (active only).
 */
export async function getPartByBarcode(barcode: string): Promise<PartCatalogItem | undefined> {
  const result = await listParts(barcode).then(parts => parts[0])
  return result ? toCatalogItem(result) : undefined
}

// ---------------------------------------------------------------------------
// Public API — Write operations
// ---------------------------------------------------------------------------

/**
 * Create a new part.
 *
 * Validates input against the create schema, then delegates to the repository.
 * After creation, inserts an initial stock movement so checkout validation works.
 * Returns the created PartDetail derived from shared Product type.
 */
export async function createPart(input: CreatePartInput): Promise<PartDetail> {
  const validated = createPartSchema.parse(input)

  // Generate ID if not provided (UUID-like format)
  const id = input.id ?? crypto.randomUUID()

  const part = await repoCreatePart({ ...validated, id })

  // Create initial stock movement so checkout validation works
  const createdQuantity = Number(validated.quantityOnHand)
  await repoCreateStockMovement({
    partId: id,
    quantityDelta: createdQuantity,
    reason: 'initial_stock'
  })

  return toPartDetail(part)
}

/**
 * Update an existing part with partial data.
 *
 * Validates that at least one field is provided. If quantityOnHand changes,
 * inserts an adjustment stock movement so checkout validation stays accurate.
 * Returns the updated PartDetail derived from shared Product type.
 */
export async function updatePart(id: string, input: UpdatePartInput): Promise<PartDetail> {
  const validated = updatePartSchema.parse(input)

  // Capture old quantityOnHand before update (needed for delta calculation)
  let oldQuantityOnHand: number | undefined
  if ('quantityOnHand' in validated) {
    const existing = await findPartById(id)
    if (!existing) throw new PartNotFoundError(id)
    oldQuantityOnHand = existing.quantityOnHand
  }

  const part = await repoUpdatePart(id, validated)

  // Create adjustment movement only when quantityOnHand actually changed
  if (oldQuantityOnHand !== undefined && 'quantityOnHand' in validated) {
    const newQuantity = Number(validated.quantityOnHand)
    const delta = newQuantity - oldQuantityOnHand
    if (delta !== 0) {
      await repoCreateStockMovement({
        partId: id,
        quantityDelta: delta,
        reason: 'adjustment'
      })
    }
  }

  return toPartDetail(part)
}

/**
 * Soft-disable a part by setting isActive to false.
 */
export async function deactivatePart(id: string): Promise<void> {
  await repoDeactivatePart(id)
}

/**
 * Input for creating a special (ad-hoc) product.
 *
 * Special products are created on-the-fly during POS transactions — e.g. when
 * a customer wants to buy something not in the catalog. They auto-generate a
 * UUID-based barcode and start with quantityOnHand = 1 via an automatic stock movement.
 */
export interface CreateSpecialProductInput {
  /** Product name (required) */
  name: string
  /** Net price in cents (required, must be positive integer) */
  priceNet: number
  /** VAT rate in basis points — defaults to standard 2100 (21%) if omitted */
  vatRateBasisPoints?: number
}

/**
 * Create a special (ad-hoc) product with auto-generated barcode and initial stock.
 *
 * Generates a UUID-based barcode (`SPEC-<uuid>`), creates the part in the parts table
 * with quantityOnHand = 1, and immediately inserts a +1 stock movement row with
 * reason="manual_correction" so the item is sellable via existing sale validation logic.
 *
 * @param input — Name, priceNet, and optional vatRateBasisPoints
 * @returns The created PartDetail including the generated barcode
 */
export async function createSpecialProduct(input: CreateSpecialProductInput): Promise<PartDetail> {
  // Validate required fields
  if (!input.name || !input.priceNet) {
    throw new Error('Name and priceNet are required')
  }

  if (typeof input.priceNet !== 'number' || input.priceNet <= 0 || !Number.isInteger(input.priceNet)) {
    throw new Error('priceNet must be a positive integer')
  }

  // Auto-generate UUID-based barcode: SPEC-<uuid>
  const uuid = crypto.randomUUID()
  const barcode = `SPEC-${uuid}`

  // Create the part with quantityOnHand = 1
  const partId = crypto.randomUUID()
  const createdPart = await repoCreateSpecialPart({
    id: partId,
    barcode,
    name: input.name,
    priceNet: input.priceNet,
    quantityOnHand: 1
  })

  // Immediately insert a +1 stock movement so the item is sellable
  await repoCreateStockMovement({
    partId,
    quantityDelta: 1,
    reason: 'manual_correction'
  })

  // Convert Part to PartDetail (inline — avoids type mismatch with Product)
  return {
    id: createdPart.id,
    barcode: createdPart.barcode,
    name: createdPart.name,
    description: createdPart.description ?? undefined,
    priceNet: createdPart.priceNet,
    costPrice: createdPart.costPrice ?? undefined,
    quantityOnHand: createdPart.quantityOnHand
  }
}

// ---------------------------------------------------------------------------
// Repository layer — database access functions
// ---------------------------------------------------------------------------

/**
 * List active parts, optionally filtered by search term.
 */
async function listParts(search?: string): Promise<Part[]> {
  if (search) {
    return db
      .select()
      .from(parts)
      .where(
        and(
          eq(parts.isActive, true),
          or(
            sql`LOWER(${parts.name}) LIKE ${'%' + search.toLowerCase() + '%'}`,
            eq(parts.barcode, search)
          )
        )
      )
      .orderBy(asc(parts.name))
  }

  return db
    .select()
    .from(parts)
    .where(eq(parts.isActive, true))
    .orderBy(asc(parts.name))
}

/**
 * Count active parts, optionally filtered by search term.
 */
async function countParts(search?: string): Promise<number> {
  if (search) {
    const [{ count: total }] = await db
      .select({ count: count() })
      .from(parts)
      .where(
        and(
          eq(parts.isActive, true),
          or(
            sql`LOWER(${parts.name}) LIKE ${'%' + search.toLowerCase() + '%'}`,
            eq(parts.barcode, search)
          )
        )
      )

    return total
  }

  const [{ count: total }] = await db
    .select({ count: count() })
    .from(parts)
    .where(eq(parts.isActive, true))

  return total
}

/**
 * Find a single active part by ID.
 */
async function findPartById(id: string): Promise<Part | undefined> {
  const [result] = await db
    .select()
    .from(parts)
    .where(and(eq(parts.id, id), eq(parts.isActive, true)))

  return result ?? undefined
}

/**
 * Create a new part. Returns the created Part.
 */
async function repoCreatePart(partData: Omit<NewPart, 'isActive'>): Promise<Part> {
  const [created] = await db
    .insert(parts)
    .values({ ...partData, isActive: true })
    .returning()

  return created
}

/**
 * Update part fields. Only active parts can be modified.
 */
async function repoUpdatePart(id: string, updates: Partial<Pick<Part, 'name' | 'barcode' | 'description' | 'priceNet' | 'costPrice' | 'quantityOnHand'>>): Promise<Part> {
  const [updated] = await db
    .update(parts)
    .set(updates)
    .where(eq(parts.id, id))
    .returning()

  if (!updated) throw new PartNotFoundError(id)

  return updated
}

/**
 * Soft-disable a part by setting isActive to false.
 */
async function repoDeactivatePart(id: string): Promise<void> {
  const result = await db
    .update(parts)
    .set({ isActive: false })
    .where(eq(parts.id, id))

  if (result.changes === 0) throw new PartNotFoundError(id)
}

/**
 * Recalculate quantityOnHand from stock_movements and persist it.
 *
 * Does NOT create any movement records — just fixes the denormalized column
 * to match the source-of-truth in stock_movements.
 */
export async function reconcileStock(partId: string): Promise<PartDetail> {
  const existing = await findPartById(partId)
  if (!existing) throw new PartNotFoundError(partId)

  // Compute total delta from movements
  const [{ totalDelta }] = await db
    .select({
      totalDelta: sql<number>`COALESCE(${drizzleSum(stockMovements.quantityDelta)}, 0)`
    })
    .from(stockMovements)
    .where(eq(stockMovements.partId, partId))

  // Update the denormalized column to match
  const [updated] = await db
    .update(parts)
    .set({ quantityOnHand: Number(totalDelta) })
    .where(eq(parts.id, partId))
    .returning()

  if (!updated) throw new PartNotFoundError(partId)

  return toPartDetail(updated as Part)
}

/**
 * Create a special part with auto-generated barcode and initial stock.
 */
async function repoCreateSpecialPart(partData: Omit<NewPart, 'isActive'>): Promise<Part> {
  const [created] = await db
    .insert(parts)
    .values({ ...partData, isActive: true })
    .returning()

  return created
}

/**
 * Create a stock movement record for inventory tracking.
 */
async function repoCreateStockMovement(movementData: Omit<NewStockMovement, 'createdAt' | 'id'>): Promise<void> {
  const [created] = await db
    .insert(stockMovements)
    .values({
      ...movementData,
      id: crypto.randomUUID(),
      createdAt: new Date()
    } as NewStockMovement)
    .returning()

  void created // stock movement record created successfully
}

