async function fetchBicycleTemplates(search?: string): Promise<{ templates: BicycleTemplateCatalogItem[]; total: number }> {
  const url = search ? `/api/bicycle-templates?search=${encodeURIComponent(search)}` : '/api/bicycle-templates'
  const res = await fetch(url)
  if (!res.ok) throw new Error('Failed to fetch bicycle templates')
