  })
  if (!res.ok) {
    const err = await res.json().catch(() => ({}))
    throw new Error(err.error ?? 'Failed to create bicycle template')
  }
  return res.json()
}

async function updateBicycleTemplate(id: string, input: UpdateBicycleTemplateInput): Promise<BicycleTemplateDetail> {
  const res = await fetch(`/api/bicycle-templates/${id}`, {
    method: 'PATCH',
