export function BicycleTemplatesPage() {
  const [templates, setTemplates] = useState<BicycleTemplateCatalogItem[]>([])
  const [totalItems, setTotalItems] = useState(0)
  const [searchTerm, setSearchTerm] = useState('')
  const [currentPage, setCurrentPage] = useState(1)
  const pageSize = 20

  // Modal state
  const [modalOpen, setModalOpen] = useState(false)
  const [editingTemplate, setEditingTemplate] = useState<BicycleTemplateDetail | null>(null)
  const [submitting, setSubmitting] = useState(false)
  const [deactivatingId, setDeactivatingId] = useState<string | null>(null)

  // Form state
  const [formBrand, setFormBrand] = useState('')
  const [formModel, setFormModel] = useState('')
  const [formDescription, setFormDescription] = useState('')
  const [formBasePriceNet, setFormBasePriceNet] = useState<number | undefined>(undefined)

  // Fetch templates on search/page change
  useEffect(() => {
    let cancelled = false
    fetchBicycleTemplates(searchTerm || undefined).then(({ templates: t, total }) => {
      if (!cancelled) {
        setTemplates(t)
        setTotalItems(total)
      }
    }).catch((err) => showError(err.message))

    return () => { cancelled = true }
  }, [searchTerm, currentPage])

  // Reset page when search changes
  const handleSearchChange = useCallback((term: string) => {
    setSearchTerm(term)
    setCurrentPage(1)
  }, [])

  // Open create modal
  const openCreateModal = () => {
    setEditingTemplate(null)
    resetForm()
    setModalOpen(true)
  }

  // Open edit modal
  const openEditModal = (template: BicycleTemplateCatalogItem) => {
    fetch(`/api/bicycle-templates/${template.id}`)
      .then(res => res.json())
      .then((detail: BicycleTemplateDetail) => {
        setEditingTemplate(detail)
        setFormBrand(detail.brand)
        setFormModel(detail.model)
        setFormDescription(detail.description ?? '')
        setFormBasePriceNet(detail.basePriceNet)
        setModalOpen(true)
      })
      .catch((err) => showError(err.message))
  }

  // Close modal and reset form
  const closeModal = () => {
    setModalOpen(false)
    setEditingTemplate(null)
    resetForm()
  }

  const resetForm = () => {
    setFormBrand('')
    setFormModel('')
    setFormDescription('')
    setFormBasePriceNet(undefined)
  }

  // Submit form (create or update)
  const handleSubmit = async () => {
    if (!formBrand.trim() || !formModel.trim()) {
      showError('Brand and model are required')
      return
    }

    setSubmitting(true)
    try {
      if (editingTemplate) {
        // Update existing template
        await updateBicycleTemplate(editingTemplate.id, {
          brand: formBrand.trim(),
          model: formModel.trim(),
          description: formDescription.trim() || undefined,
          basePriceNet: formBasePriceNet,
        })
        showSuccess('Bicycle template updated')
      } else {
        // Create new template
        await createBicycleTemplate({
          brand: formBrand.trim(),
          model: formModel.trim(),
          description: formDescription.trim() || undefined,
          basePriceNet: formBasePriceNet,
        })
        showSuccess('Bicycle template created')
      }
      closeModal()
    } catch (err) {
      showError(err instanceof Error ? err.message : 'Failed to save bicycle template')
    } finally {
      setSubmitting(false)
    }
  }

  // Deactivate template with confirmation
  const handleDeactivate = async (template: BicycleTemplateCatalogItem) => {
    if (!confirm(`Deactivate "${template.brand} ${template.model}"? This cannot be undone.`)) return

    setDeactivatingId(template.id)
    try {
      await deactivateBicycleTemplate(template.id)
      showSuccess('Bicycle template deactivated')
    } catch (err) {
      showError(err instanceof Error ? err.message : 'Failed to deactivate bicycle template')
    } finally {
      setDeactivatingId(null)
    }
  }

  // Column definitions for the DataTable
  const columns: DataTableColumn<BicycleTemplateCatalogItem>[] = [
    {
      key: 'brand',
      header: 'Brand',
      render: (item) => <span className="font-medium">{item.brand}</span>,
    },
    {
      key: 'model',
      header: 'Model',
      render: (item) => <span>{item.model}</span>,
    },
    {
      key: 'basePriceNet',
      header: 'Base Price (ex. VAT)',
      render: (item) => item.basePriceNet != null ? formatCentsToEuro(item.basePriceNet) : <span className="text-muted-foreground">—</span>,
    },
    {
      key: 'actions',
      header: '',
      render: (item) => (
        <div className="flex items-center gap-2">
          <Button variant="ghost" size="sm" onClick={() => openEditModal(item)}>Edit</Button>
          <Button
            variant="ghost"
            size="sm"
            className="text-red-500 hover:text-red-600"
            disabled={deactivatingId === item.id}
            onClick={() => handleDeactivate(item)}
          >
            {deactivatingId === item.id ? '...' : 'Deactivate'}
          </Button>
        </div>
      ),
    },
  ]

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold">Bicycle Templates</h1>
        <Button onClick={openCreateModal}>Add Template</Button>
      </div>

      {/* DataTable */}
      <DataTable<BicycleTemplateCatalogItem>
        data={templates}
        columns={columns}
        searchTerm={searchTerm}
        onSearchChange={handleSearchChange}
        totalItems={totalItems}
        currentPage={currentPage}
        pageSize={pageSize}
        onPageChange={(page) => {
          if (page >= 1 && page <= Math.ceil(totalItems / pageSize)) {
            setCurrentPage(page)
          }
        }}
        emptyMessage={'No bicycle templates found. Click "Add Template" to create one.'}
      />

      {/* Create/Edit Modal */}
      <Dialog open={modalOpen} onOpenChange={(open) => !open && closeModal()}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>{editingTemplate ? 'Edit Template' : 'Add New Template'}</DialogTitle>
            <DialogDescription>
              {editingTemplate
                ? `Editing ${editingTemplate.brand} ${editingTemplate.model}`
                : 'Fill in the details for the new bicycle template.'}
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-4 py-4">
            {/* Brand */}
            <div className="space-y-2">
              <Label htmlFor="brand">Brand *</Label>
              <Input
                id="brand"
                value={formBrand}
                onChange={(e) => setFormBrand(e.target.value)}
                placeholder="e.g. Gazelle, Batavus, Koga"
              />
            </div>

            {/* Model */}
            <div className="space-y-2">
              <Label htmlFor="model">Model *</Label>
              <Input
                id="model"
                value={formModel}
                onChange={(e) => setFormModel(e.target.value)}
                placeholder="e.g. Ultimate C8 HMB"
              />
            </div>

            {/* Description */}
            <div className="space-y-2">
              <Label htmlFor="description">Description</Label>
              <Textarea
                id="description"
                value={formDescription}
                onChange={(e) => setFormDescription(e.target.value)}
                placeholder="Optional description"
                rows={2}
              />
            </div>

            {/* Base Price (optional) */}
            <div className="space-y-2">
              <Label htmlFor="basePriceNet">Base Price (ex. VAT)</Label>
              <CurrencyInput
                id="basePriceNet"
                value={formBasePriceNet ?? 0}
                onChange={(val) => setFormBasePriceNet(val > 0 ? val : undefined)}
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={closeModal}>Cancel</Button>
            <Button onClick={handleSubmit} disabled={submitting}>
              {submitting ? 'Saving...' : editingTemplate ? 'Save Changes' : 'Create Template'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

import * as React from 'react'
import { formatCentsToEuro } from '@/shared/lib/utils.js'

// ---------------------------------------------------------------------------
// Types
