      expect(res.status).toBe(404)
    })
  })

  // ========================================================================
  // POST /api/parts — Create a new part
  // ========================================================================

  describe('POST /api/parts', () => {
    it('should create a part with required fields and return 201', async () => {
      const res = await app.request('/api/parts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          barcode: 'BAR-NEW',
          name: 'New Bearing',
          priceNet: 1500,
          quantityOnHand: 20
        })
      })

      expect(res.status).toBe(201)

      const body = await res.json()
      expect(body.id).toBeDefined()
      expect(body.barcode).toBe('BAR-NEW')
      expect(body.name).toBe('New Bearing')
      expect(body.priceNet).toBe(1500)
      expect(body.quantityOnHand).toBe(20)
    })

    it('should accept optional description and costPrice', async () => {
      const res = await app.request('/api/parts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          barcode: 'BAR-OPT',
          name: 'Optional Fields Part',
          priceNet: 1000,
          quantityOnHand: 5,
          description: 'A part with optional fields',
          costPrice: 600
        })
      })

      expect(res.status).toBe(201)

      const body = await res.json()
      expect(body.description).toBe('A part with optional fields')
      expect(body.costPrice).toBe(600)
    })

    it('should reject missing required fields', async () => {
      const res = await app.request('/api/parts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ barcode: '', name: 'Test', priceNet: 100, quantityOnHand: 5 })
      })

      expect(res.status).toBe(400)

      const body = await res.json()
      expect(body.success).toBe(false)
      expect(body.error.issues).toBeDefined()
    })

    it('should reject negative price', async () => {
      const res = await app.request('/api/parts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ barcode: 'BAR-NEG', name: 'Negative Price Part', priceNet: -100, quantityOnHand: 5 })
      })

      expect(res.status).toBe(400)
    })

    it('should reject negative quantity on hand', async () => {
      const res = await app.request('/api/parts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ barcode: 'BAR-NEG-QTY', name: 'Negative Qty Part', priceNet: 100, quantityOnHand: -5 })
      })

      expect(res.status).toBe(400)
    })
  })

  // ========================================================================
  // PATCH /api/parts/:id — Update a part (partial update allowed)
  // ========================================================================

  describe('PATCH /api/parts/:id', () => {
    it('should update part fields and return updated PartDetail', async () => {
      await db.insert(parts).values({ id: 'p1', barcode: 'BAR-OLD', name: 'Old Name', priceNet: 1000, quantityOnHand: 5 })

      const res = await app.request('/api/parts/p1', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: 'New Name', priceNet: 2000 })
      })

      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.name).toBe('New Name')
      expect(body.priceNet).toBe(2000)
    })

    it('should allow partial updates (only provided fields change)', async () => {
      await db.insert(parts).values({ id: 'p1', barcode: 'BAR-PARTIAL', name: 'Original', priceNet: 1000, quantityOnHand: 5 })

      const res = await app.request('/api/parts/p1', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ description: 'New description' })
      })

      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.name).toBe('Original')
      expect(body.description).toBe('New description')
    })

    it('should reject empty update payload', async () => {
      await db.insert(parts).values({ id: 'p1', barcode: 'BAR-EMPTY', name: 'Test', priceNet: 100, quantityOnHand: 5 })

      const res = await app.request('/api/parts/p1', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({})
      })

      expect(res.status).toBe(400)
    })

    it('should reject negative price in update', async () => {
      await db.insert(parts).values({ id: 'p1', barcode: 'BAR-NEG', name: 'Test', priceNet: 100, quantityOnHand: 5 })

      const res = await app.request('/api/parts/p1', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ priceNet: -50 })
      })

      expect(res.status).toBe(400)
    })

    it('should return 404 for non-existent part', async () => {
      const res = await app.request('/api/parts/nonexistent', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: 'Ghost' })
      })

      expect(res.status).toBe(404)
    })
  })

  // ========================================================================
  // PATCH /api/parts/:id/deactivate — Soft-delete a part
  // ========================================================================

  describe('PATCH /api/parts/:id/deactivate', () => {
    it('should soft-disable a part and return success', async () => {
      await db.insert(parts).values({ id: 'p1', barcode: 'BAR-DEACT', name: 'To Deactivate', priceNet: 1000, quantityOnHand: 5 })

      const res = await app.request('/api/parts/p1/deactivate', {
        method: 'PATCH'
      })

      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.success).toBe(true)
    })

    it('should exclude deactivated part from browse results', async () => {
      await db.insert(parts).values({ id: 'p1', barcode: 'BAR-DEACT2', name: 'Deactivated', priceNet: 1000, quantityOnHand: 5 })

      // Deactivate first
      await app.request('/api/parts/p1/deactivate', { method: 'PATCH' })

      // Verify it's gone from browse
      const res = await app.request('/api/parts')
      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.parts).toHaveLength(0)
    })

    it('should return 404 for non-existent part', async () => {
      const res = await app.request('/api/parts/nonexistent/deactivate', { method: 'PATCH' })
      expect(res.status).toBe(404)
    })
  })

  // ==========================================================================
  // Stock Movement — Route Integration (Issue #154)
  // ==========================================================================

  describe('POST /api/parts stock movement', () => {
    it('should create an initial_stock movement when creating a part via API', async () => {
      const res = await app.request('/api/parts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          barcode: 'BAR-API-1',
          name: 'API Bearing',
          priceNet: 1500,
          quantityOnHand: 20
        })
      })

      expect(res.status).toBe(201)
      const body = await res.json() as { id: string; barcode: string; name: string; priceNet: number; quantityOnHand: number }
      expect(body.quantityOnHand).toBe(20)

      const movements = await db.select().from(stockMovements).where(eq(stockMovements.partId, body.id))
      expect(movements).toHaveLength(1)
      expect(movements[0].quantityDelta).toBe(20)
      expect(movements[0].reason).toBe('initial_stock')
    })
  })

  describe('PATCH /api/parts/:id stock movement', () => {
    it('should create an adjustment movement when quantityOnHand increases via API', async () => {
      await db.insert(parts).values({ id: 'p-api-1', barcode: 'BAR-API-2', name: 'API Part', priceNet: 1000, quantityOnHand: 5 })

      const res = await app.request('/api/parts/p-api-1', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ quantityOnHand: 25 })
      })

      expect(res.status).toBe(200)
      const body = await res.json() as { id: string; quantityOnHand: number }
      expect(body.quantityOnHand).toBe(25)

      const movements = await db.select().from(stockMovements).where(eq(stockMovements.partId, 'p-api-1'))
      expect(movements).toHaveLength(1)
      expect(movements[0].quantityDelta).toBe(20) // 25 - 5
      expect(movements[0].reason).toBe('adjustment')
    })

    it('should NOT create a movement when only name changes via API', async () => {
      await db.insert(parts).values({ id: 'p-api-2', barcode: 'BAR-API-3', name: 'Original Name', priceNet: 1000, quantityOnHand: 5 })

      const res = await app.request('/api/parts/p-api-2', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: 'New Name' })
      })

      expect(res.status).toBe(200)

      const movements = await db.select().from(stockMovements).where(eq(stockMovements.partId, 'p-api-2'))
      expect(movements).toHaveLength(0)
    })
  })
})

