import { describe, it, expect, beforeEach } from 'vitest'
import app from '@/app.js'
import { db } from '@/db/index.js'
import { bicycleTemplates } from '@/db/schema.js'

describe('Bicycle Templates Routes', () => {
  async function resetTemplates() {
    await db.delete(bicycleTemplates)
  }

  beforeEach(async () => {
    await resetTemplates()
  })

  // ========================================================================
  // GET /api/bicycle-templates — Browse catalog (verify API contract unchanged)
  // ========================================================================

  describe('GET /api/bicycle-templates', () => {
    it('should return 200 with empty array when no templates exist', async () => {
      const res = await app.request('/api/bicycle-templates')
      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body).toEqual({ templates: [], total: 0 })
    })

    it('should return active templates with correct response shape', async () => {
      await db.insert(bicycleTemplates).values([
        { id: 't1', brand: 'Gazelle', model: 'Ultimate C8 HMB' },
        { id: 't2', brand: 'Batavus', model: 'Gold Crown' }
      ])

      const res = await app.request('/api/bicycle-templates')
      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.templates).toHaveLength(2)
      expect(body.total).toBe(2)

      // Verify response shape
      const template = body.templates[0]
      expect(template).toHaveProperty('id')
      expect(template).toHaveProperty('brand')
      expect(template).toHaveProperty('model')

      // Verify no extra fields
      const expectedKeys = ['id', 'brand', 'model']
      expect(Object.keys(template)).toEqual(expectedKeys)
    })

    it('should exclude inactive templates from response', async () => {
      await db.insert(bicycleTemplates).values([
        { id: 't1', brand: 'Active Brand', model: 'Model A' },
        { id: 't2', brand: 'Inactive Brand', model: 'Model B', isActive: false }
      ])

      const res = await app.request('/api/bicycle-templates')
      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.templates).toHaveLength(1)
      expect(body.templates[0].brand).toBe('Active Brand')
    })

    it('should filter by brand search (case-insensitive partial match)', async () => {
      await db.insert(bicycleTemplates).values([
        { id: 't1', brand: 'Gazelle', model: 'Ultimate C8 HMB' },
        { id: 't2', brand: 'Batavus', model: 'Gold Crown' },
        { id: 't3', brand: 'Koga', model: 'Sportster' }
      ])

      const res = await app.request('/api/bicycle-templates?search=gazel')
      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.templates).toHaveLength(1)
      expect(body.templates[0].brand).toBe('Gazelle')
      expect(body.total).toBe(1)
    })

    it('should filter by model search (case-insensitive partial match)', async () => {
      await db.insert(bicycleTemplates).values([
        { id: 't1', brand: 'Gazelle', model: 'Ultimate C8 HMB' },
        { id: 't2', brand: 'Batavus', model: 'Gold Crown' }
      ])

      const res = await app.request('/api/bicycle-templates?search=ultimate')
      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.templates).toHaveLength(1)
      expect(body.templates[0].model).toBe('Ultimate C8 HMB')
    })

    it('should handle case-insensitive brand search', async () => {
      await db.insert(bicycleTemplates).values([
        { id: 't1', brand: 'Gazelle', model: 'Ultimate C8 HMB' }
      ])

      const res = await app.request('/api/bicycle-templates?search=GAZELLE')
      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.templates).toHaveLength(1)
      expect(body.templates[0].brand).toBe('Gazelle')
    })

    it('should return empty results for non-matching search', async () => {
      await db.insert(bicycleTemplates).values([
        { id: 't1', brand: 'Gazelle', model: 'Ultimate C8 HMB' }
      ])

      const res = await app.request('/api/bicycle-templates?search=nonexistent')
      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.templates).toEqual([])
      expect(body.total).toBe(0)
    })

    it('should return results ordered by brand then model', async () => {
      await db.insert(bicycleTemplates).values([
        { id: 't3', brand: 'Zebra Cycles', model: 'Model Z' },
        { id: 't1', brand: 'Alpha Bikes', model: 'Model A' },
        { id: 't2', brand: 'Beta Cycles', model: 'Model B' }
      ])

      const res = await app.request('/api/bicycle-templates')
      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.templates.map((t: { brand: string }) => t.brand)).toEqual(['Alpha Bikes', 'Beta Cycles', 'Zebra Cycles'])
    })

    it('should return correct total count with search filter', async () => {
      await db.insert(bicycleTemplates).values([
        { id: 't1', brand: 'Gazelle', model: 'Ultimate' },
        { id: 't2', brand: 'Batavus', model: 'Gold' },
        { id: 't3', brand: 'Gazelle', model: 'Sport' }
      ])

      const res = await app.request('/api/bicycle-templates?search=gazel')
      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.total).toBe(2)
    })

    it('should include basePriceNet when set', async () => {
      await db.insert(bicycleTemplates).values([
        { id: 't1', brand: 'Gazelle', model: 'Premium', basePriceNet: 250000 }
      ])

      const res = await app.request('/api/bicycle-templates')
      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.templates[0].basePriceNet).toBe(250000)
    })
  })

  // ========================================================================
  // GET /api/bicycle-templates/:id — Get single template detail
  // ========================================================================

  describe('GET /api/bicycle-templates/:id', () => {
    it('should return a template by ID with full detail shape', async () => {
      await db.insert(bicycleTemplates).values({
        id: 't1', brand: 'Gazelle', model: 'Ultimate C8 HMB',
        description: 'Premium city bike', basePriceNet: 250000
      })

      const res = await app.request('/api/bicycle-templates/t1')
      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.id).toBe('t1')
      expect(body.brand).toBe('Gazelle')
      expect(body.model).toBe('Ultimate C8 HMB')
      expect(body.description).toBe('Premium city bike')
      expect(body.basePriceNet).toBe(250000)
    })

    it('should return 404 for non-existent template', async () => {
      const res = await app.request('/api/bicycle-templates/nonexistent')
      expect(res.status).toBe(404)

      const body = await res.json()
      expect(body.error).toBe('Bicycle template not found')
    })

    it('should return 404 for inactive template', async () => {
      await db.insert(bicycleTemplates).values({ id: 't1', brand: 'Inactive Brand', model: 'Model B', isActive: false })

      const res = await app.request('/api/bicycle-templates/t1')
      expect(res.status).toBe(404)
    })
  })

  // ========================================================================
  // POST /api/bicycle-templates — Create a new template
  // ========================================================================

  describe('POST /api/bicycle-templates', () => {
    it('should create a template with required fields and return 201', async () => {
      const res = await app.request('/api/bicycle-templates', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          brand: 'Gazelle',
          model: 'Ultimate C8 HMB'
        })
      })

      expect(res.status).toBe(201)

      const body = await res.json()
      expect(body.id).toBeDefined()
      expect(body.brand).toBe('Gazelle')
      expect(body.model).toBe('Ultimate C8 HMB')
    })

    it('should accept optional description and basePriceNet', async () => {
      const res = await app.request('/api/bicycle-templates', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          brand: 'Batavus',
          model: 'Gold Crown',
          description: 'Classic Dutch bike',
          basePriceNet: 200000
        })
      })

      expect(res.status).toBe(201)

      const body = await res.json()
      expect(body.description).toBe('Classic Dutch bike')
      expect(body.basePriceNet).toBe(200000)
    })

    it('should reject missing required fields', async () => {
      const res = await app.request('/api/bicycle-templates', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ brand: '', model: 'Test' })
      })

      expect(res.status).toBe(400)

      const body = await res.json()
      expect(body.success).toBe(false)
      expect(body.error.issues).toBeDefined()
    })
  })

  // ========================================================================
  // PATCH /api/bicycle-templates/:id — Update a template (partial update allowed)
  // ========================================================================

  describe('PATCH /api/bicycle-templates/:id', () => {
    it('should update template fields and return updated BicycleTemplateDetail', async () => {
      await db.insert(bicycleTemplates).values({ id: 't1', brand: 'Old Brand', model: 'Old Model' })

      const res = await app.request('/api/bicycle-templates/t1', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ brand: 'New Brand', model: 'New Model' })
      })

      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.brand).toBe('New Brand')
      expect(body.model).toBe('New Model')
    })

    it('should allow partial updates (only provided fields change)', async () => {
      await db.insert(bicycleTemplates).values({ id: 't1', brand: 'Original', model: 'Model A', description: 'Old desc' })

      const res = await app.request('/api/bicycle-templates/t1', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ description: 'New description' })
      })

      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.brand).toBe('Original')
      expect(body.description).toBe('New description')
    })

    it('should reject empty update payload', async () => {
      await db.insert(bicycleTemplates).values({ id: 't1', brand: 'Test', model: 'Model' })

      const res = await app.request('/api/bicycle-templates/t1', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({})
      })

      expect(res.status).toBe(400)
    })

    it('should return 404 for non-existent template', async () => {
      const res = await app.request('/api/bicycle-templates/nonexistent', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ brand: 'Ghost' })
      })

      expect(res.status).toBe(404)
    })
  })

  // ========================================================================
  // PATCH /api/bicycle-templates/:id/deactivate — Soft-disable a template
  // ========================================================================

  describe('PATCH /api/bicycle-templates/:id/deactivate', () => {
    it('should soft-disable a template and return success', async () => {
      await db.insert(bicycleTemplates).values({ id: 't1', brand: 'To Deactivate', model: 'Model' })

      const res = await app.request('/api/bicycle-templates/t1/deactivate', {
        method: 'PATCH'
      })

      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.success).toBe(true)
    })

    it('should exclude deactivated template from browse results', async () => {
      await db.insert(bicycleTemplates).values({ id: 't1', brand: 'Deactivated', model: 'Model' })

      // Deactivate first
      await app.request('/api/bicycle-templates/t1/deactivate', { method: 'PATCH' })

      // Verify it's gone from browse
      const res = await app.request('/api/bicycle-templates')
      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.templates).toHaveLength(0)
    })

    it('should return 404 for non-existent template', async () => {
      const res = await app.request('/api/bicycle-templates/nonexistent/deactivate', { method: 'PATCH' })
      expect(res.status).toBe(404)
    })
  })
})

